#!/usr/bin/env python3
import concurrent.futures
import json
import os
import re
import statistics
import subprocess
import threading
import time
import uuid
from pathlib import Path

AENV = "/var/lib/preloop/benchmarks/AgentENV/target/release/aenv"
SMOLVM = "/usr/local/bin/smolvm"
OUT = Path("/var/lib/preloop/benchmarks/aenv-smolvm-results.json")
CONCURRENCIES = [1, 2, 4, 8, 12]
REPEATS = 2
UUID_RE = re.compile(r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}")

WORKLOADS = {
    "alpine_shell": {
        "image": "alpine:3.20",
        "command": ["sh", "-c", "i=0; while [ $i -lt 1000000 ]; do i=$((i+1)); done; dd if=/dev/zero of=/tmp/aenv-bench.bin bs=1M count=32 conv=fdatasync 2>/dev/null; sha256sum /tmp/aenv-bench.bin >/dev/null; rm -f /tmp/aenv-bench.bin"],
    },
    "python_compute": {
        "image": "python:3.12-alpine",
        "command": ["python", "-c", "import hashlib; x=b'x'*1048576; [hashlib.sha256(x).digest() for _ in range(128)]"],
    },
    "node_json": {
        "image": "node:22-alpine",
        "command": ["node", "-e", "const a=Array.from({length:100000},(_,i)=>({i,v:i%17,s:'payload'})); JSON.parse(JSON.stringify(a));"],
    },
}


def proc(args, timeout=180):
    return subprocess.run(args, text=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, timeout=timeout)


def host_snapshot():
    mem = {}
    for line in Path("/proc/meminfo").read_text().splitlines():
        k, _, v = line.partition(":")
        if k in ("MemTotal", "MemAvailable", "SwapFree"):
            try:
                mem[k] = int(v.strip().split()[0]) * 1024
            except Exception:
                pass
    load = tuple(float(x) for x in Path("/proc/loadavg").read_text().split()[:3])
    return {"mem": mem, "load": load, "ts": time.time()}


def monitor(stop, samples):
    while not stop.is_set():
        try:
            samples.append(host_snapshot())
        except Exception:
            pass
        stop.wait(0.2)


def extract_id(text):
    matches = UUID_RE.findall(text)
    return matches[-1] if matches else None


def run_agentenv(workload, index):
    name = None
    t0 = time.perf_counter()
    result = {"backend": "agentenv", "index": index, "ok": False}
    try:
        p = proc([AENV, "start", "--cold", workload["image"], "--cpu", "1", "--memory", "512", "--disk-size-mb", "2048", "--detach"], 240)
        t_start_return = time.perf_counter()
        name = extract_id(p.stdout)
        if p.returncode or not name:
            result["error"] = f"start rc={p.returncode}: {p.stdout[-1000:]}"
            return result
        result["start_ms"] = (t_start_return - t0) * 1000
        ready_start = time.perf_counter()
        ready = False
        while time.perf_counter() - ready_start < 45:
            q = proc([AENV, "exec", name, "sh", "-c", "true"], 30)
            if q.returncode == 0:
                ready = True
                break
            time.sleep(0.1)
        result["ready_ms"] = (time.perf_counter() - ready_start) * 1000
        if not ready:
            result["error"] = "readiness timeout"
            return result
        w0 = time.perf_counter()
        q = proc([AENV, "exec", name, *workload["command"]], 180)
        result["workload_ms"] = (time.perf_counter() - w0) * 1000
        if q.returncode:
            result["error"] = f"workload rc={q.returncode}: {q.stdout[-1000:]}"
            return result
        result["ok"] = True
    except Exception as e:
        result["error"] = repr(e)
    finally:
        if name:
            try:
                proc([AENV, "delete", name], 30)
            except Exception:
                pass
        result["total_ms"] = (time.perf_counter() - t0) * 1000
    return result


def run_smolvm(workload, index):
    name = f"bench-{uuid.uuid4().hex[:12]}"
    t0 = time.perf_counter()
    result = {"backend": "smolvm", "index": index, "ok": False}
    try:
        p = proc([SMOLVM, "machine", "create", "--name", name, "--image", workload["image"], "--cpus", "1", "--mem", "512", "--storage", "8", "--overlay", "4"], 240)
        if p.returncode:
            result["error"] = f"create rc={p.returncode}: {p.stdout[-1000:]}"
            return result
        p = proc([SMOLVM, "machine", "start", "--name", name], 240)
        t_start_return = time.perf_counter()
        if p.returncode:
            result["error"] = f"start rc={p.returncode}: {p.stdout[-1000:]}"
            return result
        result["start_ms"] = (t_start_return - t0) * 1000
        ready_start = time.perf_counter()
        ready = False
        while time.perf_counter() - ready_start < 45:
            q = proc([SMOLVM, "machine", "exec", "--name", name, "--", "sh", "-c", "true"], 30)
            if q.returncode == 0:
                ready = True
                break
            time.sleep(0.1)
        result["ready_ms"] = (time.perf_counter() - ready_start) * 1000
        if not ready:
            result["error"] = "readiness timeout"
            return result
        w0 = time.perf_counter()
        q = proc([SMOLVM, "machine", "exec", "--name", name, "--", *workload["command"]], 180)
        result["workload_ms"] = (time.perf_counter() - w0) * 1000
        if q.returncode:
            result["error"] = f"workload rc={q.returncode}: {q.stdout[-1000:]}"
            return result
        result["ok"] = True
    except Exception as e:
        result["error"] = repr(e)
    finally:
        try:
            proc([SMOLVM, "machine", stop := "stop", "--name", name], 30)
        except Exception:
            pass
        try:
            proc([SMOLVM, "machine", "delete", "--name", name, "-f", "--cascade"], 30)
        except Exception:
            pass
        result["total_ms"] = (time.perf_counter() - t0) * 1000
    return result


def summary(rows):
    def stats(key):
        vals = sorted(r[key] for r in rows if r.get("ok") and key in r)
        if not vals:
            return {}
        def pct(p):
            if len(vals) == 1:
                return vals[0]
            pos = (len(vals) - 1) * p
            lo, hi = int(pos), min(int(pos) + 1, len(vals) - 1)
            return vals[lo] + (vals[hi] - vals[lo]) * (pos - lo)
        return {"n": len(vals), "min": vals[0], "p50": pct(.50), "p95": pct(.95), "p99": pct(.99), "max": vals[-1], "mean": statistics.mean(vals)}
    return {"completed": sum(1 for r in rows if r.get("ok")), "failed": sum(1 for r in rows if not r.get("ok")), "metrics": {k: stats(k) for k in ("start_ms", "ready_ms", "workload_ms", "total_ms")}}


def main():
    all_results = {"host": {"hostname": os.uname().nodename, "cpu_count": os.cpu_count(), "started": time.time()}, "workloads": {}, "summaries": {}}
    for workload_name, workload in WORKLOADS.items():
        for backend, fn in (("agentenv", run_agentenv), ("smolvm", run_smolvm)):
            for concurrency in CONCURRENCIES:
                key = f"{workload_name}/{backend}/c{concurrency}"
                print(f"RUN {key}", flush=True)
                samples = []
                stop = threading.Event()
                thread = threading.Thread(target=monitor, args=(stop, samples), daemon=True)
                thread.start()
                rows = []
                batch_start = time.time()
                with concurrent.futures.ThreadPoolExecutor(max_workers=concurrency) as pool:
                    futures = [pool.submit(fn, workload, i) for i in range(concurrency)]
                    for future in futures:
                        rows.append(future.result())
                stop.set(); thread.join(timeout=1)
                all_results["workloads"][key] = {"rows": rows, "host_samples": samples, "batch_seconds": time.time() - batch_start}
                all_results["summaries"][key] = summary(rows)
                print(json.dumps({"key": key, **all_results["summaries"][key]}), flush=True)
                OUT.write_text(json.dumps(all_results, indent=2))
    all_results["host"]["finished"] = time.time()
    OUT.write_text(json.dumps(all_results, indent=2))

if __name__ == "__main__":
    main()

